class Solution {
public:
    int deleteGreatestValue(vector<vector<int>>& grid) {
        int m = grid.size();
        int n = grid[0].size();
        int count[101];

        for (int i = 0; i < m; i++) {
            for (int v = 0; v <= 100; v++) count[v] = 0;
            for (int j = 0; j < n; j++) count[grid[i][j]]++;
            int idx = 0;
            for (int v = 100; v >= 1; v--) {
                while (count[v] > 0) {
                    grid[i][idx++] = v;
                    count[v]--;
                }
            }
        }

        int answer = 0;
        for (int j = 0; j < n; j++) {
            int colMax = 0;
            for (int i = 0; i < m; i++) {
                if (grid[i][j] > colMax) colMax = grid[i][j];
            }
            answer += colMax;
        }

        return answer;
    }
};
